from math import comb

def f(n):
    # f(n) = min_{N_R+N_B=n} (comb(N_R, 3) + comb(N_B, 3))
    # The minimum occurs when N_R and N_B are as close as possible.
    n_r = n // 2
    n_b = n - n_r
    return comb(n_r, 3) + comb(n_b, 3)

# Check values up to n=8
for n in range(1, 9):
    print(f"f({n}) = {f(n)}")

from itertools import combinations

def combinations_of_3(k):
    if k < 3:
        return 0
    # Using the formula C(k, 3) = k * (k-1) * (k-2) / 6
    return k * (k - 1) * (k - 2) // 6

results = {}

for n in range(1, 6):
    min_value = float('inf')
    best_distribution = None

    # Iterate through all possible partitions (Nr, Nb) where Nr + Nb = n
    for Nr in range(n + 1):
        Nb = n - Nr

        # Calculate the number of monochromatic triangles based on the hypothesis
        total_monochromatic = combinations_of_3(Nr) + combinations_of_3(Nb)

        if total_monochromatic < min_value:
            min_value = total_monochromatic
            # Store the distribution, ensuring standard order (Nr <= Nb) for consistency
            best_distribution = tuple(sorted((Nr, Nb)))

    results[n] = {
        'min_monochromatic': min_value,
        'best_distribution': best_distribution
    }

for n, data in results.items():
    print(f"n = {n}: Minimum monochromatic triangles = {data['min_monochromatic']}, Achieved with distribution {data['best_distribution']}")

